<template>
  <aside class="workday cards" :class="[`theme-${theme}`]" aria-label="今日工作台">
    <header class="panel-header">
      <div><p class="eyebrow">TODAY'S FOCUS</p><h1>今日工作台</h1></div>
      <div class="header-actions"><span class="date-label">{{ currentTime.month }} 月 {{ currentTime.day }} 日</span><button class="icon-button" type="button" aria-label="数据管理" @click="showDataMenu = !showDataMenu">···</button></div>
      <div v-if="showDataMenu" class="data-menu">
        <button type="button" @click="downloadExcel">导出 Excel</button>
        <button type="button" @click="downloadExport">导出我的数据</button>
        <button type="button" @click="importInput?.click()">导入备份</button>
        <button class="danger" type="button" @click="openClearDialog">清空本地数据</button>
      </div>
      <input ref="importInput" class="sr-only" type="file" accept="application/json,.json" @change="prepareImport" />
    </header>


    <section class="focus-now" :class="{ running: activeTimer?.status === 'running' }">
      <div class="focus-copy">
        <span class="status-dot" /><p>{{ activeTimer ? (activeTimer.mode === "countdown" ? "正在倒计时" : "正在正向计时") : "当前下一件事" }}</p>
        <h2>{{ activeTask?.title || currentTask?.title || focusTask?.title || "从今日计划选择一件事" }}</h2>
        <small v-if="activeTimer">{{ activeTimer.mode === "countdown" ? `计划 ${Math.round(activeTimer.plannedSeconds / 60)} 分钟` : "自由专注时长" }}</small>
        <small v-else>{{ focusTask ? "已从今日计划选中，准备好后开始 25 分钟" : "先安排一件任务到今日计划，再开始专注" }}</small>
      </div>
      <div class="timer">
        <strong>{{ formattedTime }}</strong>
        <div v-if="!activeTimer" class="focus-mode" aria-label="专注计时方式">
          <button type="button" class="mode-choice" :class="{ selected: focusMode === 'countdown' }" @click="focusMode = 'countdown'">25 分钟</button>
          <button type="button" class="mode-choice" :class="{ selected: focusMode === 'stopwatch' }" @click="focusMode = 'stopwatch'">正向计时</button>
        </div>
        <button v-if="!activeTimer" class="start-focus" type="button" :disabled="!focusTask" @click="startDefaultFocus">{{ focusMode === 'countdown' ? '开始专注 · 25 分钟' : '开始正向计时' }}</button>
        <template v-else-if="activeTimer.status === 'running'"><button type="button" @click="pauseTimer">暂停</button><button type="button" @click="requestTimerEnd">结束本轮</button><button type="button" @click="abandonTimer">放弃</button></template>
        <template v-else><button type="button" @click="resumeTimer">继续</button><button type="button" @click="requestTimerEnd">结束本轮</button><button type="button" @click="abandonTimer">放弃</button></template>
      </div>
    </section>

    <section class="task-pool" aria-labelledby="task-pool-title">
      <div class="section-title"><div><p class="eyebrow">TASK VIEWS</p><h2 id="task-pool-title">{{ taskViewLabel }}</h2></div><div class="section-actions"><button class="text-button" type="button" @click="openScheduleDialog">+ 安排</button><button class="text-button" type="button" @click="showTaskDialog = true">+ 新任务</button></div></div>
      <div class="task-tabs" role="tablist" aria-label="任务视图"><button v-for="view in taskViews" :key="view.id" type="button" :class="{ selected: taskView === view.id }" @click="taskView = view.id">{{ view.label }} <small>{{ view.count }}</small></button></div>
      <div v-if="visibleTasks.length" class="task-grid">
        <article v-for="(task, index) in visibleTasks" :key="task.id" class="task" :class="[task.quadrant, { selected: selectedTaskId === task.id, 'focus-source': focusTask?.id === task.id, done: task.status === 'completed' }]">
          <button class="task-main" type="button" @click="selectedTaskId = task.id"><span>{{ task.title }}</span></button>
          <div class="task-actions">
            <button class="task-order" type="button" :disabled="index === 0" aria-label="提高优先级" title="提高优先级" @click="moveVisibleTask(index, -1)">↑</button>
            <button class="task-order" type="button" :disabled="index === visibleTasks.length - 1" aria-label="降低优先级" title="降低优先级" @click="moveVisibleTask(index, 1)">↓</button>
            <button v-if="task.status !== 'active'" class="task-check" type="button" aria-label="完成任务" title="完成任务" @click="requestCompleteTask(task.id)">○</button>
            <button class="task-delete" type="button" aria-label="删除任务" title="删除任务" @click="requestDeleteTask(task.id)">×</button>
          </div>
        </article>
      </div>
      <div v-else class="empty-tasks"><span>{{ taskView === 'now' ? '当前没有专注任务。' : taskView === 'today' ? '今天尚未安排任务。' : '收件箱已清空。' }}</span><button v-if="taskView !== 'inbox'" type="button" @click="showTaskDialog = true">创建任务</button></div>
    </section>

    <div v-if="showTaskDialog || showScheduleDialog || showFocusEndDialog || importPreview || showClearDialog" class="dialog-backdrop" @click.self="dismissBackdrop">
      <section v-if="showFocusEndDialog" class="dialog focus-end-dialog"><h2>这一轮先到这里</h2><p class="dialog-subtitle">{{ activeTask?.title }} 的本轮专注将被保存。接下来怎么做？</p><footer><button type="button" @click="settleFocus('continue')">继续专注 25 分钟</button><button type="button" @click="settleFocus('complete')">完成任务</button><button class="primary" type="button" @click="settleFocus('rest')">保存本轮并休息</button></footer></section>
      <form v-else-if="showTaskDialog" class="dialog" @submit.prevent="createTask"><h2>新建任务</h2><label>任务名称<input v-model="taskForm.title" required maxlength="60" placeholder="例如：完成数据模型" /></label><p class="dialog-subtitle">创建后请安排到今日计划，再开始专注。</p><p v-if="formError" class="error">{{ formError }}</p><footer><button type="button" @click="closeDialogs">取消</button><button class="primary" type="submit">创建任务</button></footer></form>
      <form v-else-if="showScheduleDialog" class="dialog" @submit.prevent="createSchedule"><h2>安排任务</h2><label>任务<select v-model="scheduleForm.taskId"><option disabled value="">选择任务</option><option v-for="task in availableTasks" :key="task.id" :value="task.id">{{ task.title }}</option></select></label><label>开始时间<input v-model="scheduleForm.startTime" type="time" min="08:30" max="20:30" /></label><label>预计分钟<input v-model.number="scheduleForm.durationMinutes" type="number" min="5" max="720" /></label><p class="dialog-subtitle">工作时间为 08:30—20:30；安排后会出现在“今日计划”。</p><p v-if="formError" class="error">{{ formError }}</p><footer><button type="button" @click="closeDialogs">取消</button><button class="primary" type="submit">加入今日计划</button></footer></form>
      <section v-else-if="importPreview" class="dialog"><h2>导入备份</h2><p>将导入 {{ importPreview.tasks.length }} 个任务、{{ importPreview.scheduleBlocks.length }} 个计划和 {{ importPreview.focusSessions.length }} 条专注记录。</p><p class="dialog-subtitle">合并会按 ID 保留当前数据；替换会覆盖当前全部数据。</p><footer><button type="button" @click="closeDialogs">取消</button><button type="button" @click="applyImport('merge')">合并导入</button><button class="danger-button" type="button" @click="applyImport('replace')">替换全部</button></footer></section>
      <section v-else class="dialog"><h2>清空本地数据</h2><p>此操作会删除此浏览器中所有任务、计划、专注记录和设置，无法撤销。</p><label>输入“清空”确认<input v-model="clearPhrase" autocomplete="off" /></label><footer><button type="button" @click="closeDialogs">取消</button><button class="danger-button" type="button" :disabled="clearPhrase !== '清空'" @click="confirmClear">清空全部数据</button></footer></section>
    </div>
  </aside>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { usePomodoroStore } from "@/stores/pomodoroStore";
import { createExcelWorkbook, downloadFile } from "@/utils/analyticsExport";


const props = defineProps({ currentTime: { type: Object, required: true }, theme: { type: String, default: "day" } });
const { state, currentWorkday, activeTask, currentTask, todaySessions, addTask, completeTask, deleteTask, moveTask, addScheduleBlock, removeScheduleBlock, startTimer, pauseTimer, resumeTimer, settleTimer, discardTimer, getElapsedSeconds, exportData, importData, clearAllData, refreshWorkday } = usePomodoroStore();
const selectedTaskId = ref(""); const taskView = ref("today"); const focusMode = ref("countdown"); const showDataMenu = ref(false); const showTaskDialog = ref(false); const showScheduleDialog = ref(false); const showFocusEndDialog = ref(false); const showClearDialog = ref(false); const importPreview = ref(null); const importText = ref(""); const importInput = ref(null); const clearPhrase = ref(""); const formError = ref(""); const elapsedSeconds = ref(0); let clock;
const taskForm = ref({ title: "", quadrant: "important", estimatePomodoros: 1 }); const scheduleForm = ref({ taskId: "", startTime: "09:00", durationMinutes: 50 });
const activeTimer = computed(() => state.value.activeTimer); const availableTasks = computed(() => state.value.tasks.filter((task) => ["inbox", "planned", "active"].includes(task.status))); const inboxTasks = computed(() => state.value.tasks.filter((task) => task.status === "inbox")); const todayTasks = computed(() => { const ids = new Set(state.value.scheduleBlocks.filter((block) => block.workday === currentWorkday.value && block.status === "planned").map((block) => block.taskId)); return state.value.tasks.filter((task) => ids.has(task.id) && task.status !== "completed"); }); const nowTasks = computed(() => currentTask.value ? [currentTask.value] : []); const taskViews = computed(() => [{ id: "now", label: "现在", count: nowTasks.value.length }, { id: "today", label: "今日计划", count: todayTasks.value.length }, { id: "inbox", label: "收件箱", count: inboxTasks.value.length }]); const taskViewLabel = computed(() => taskViews.value.find((view) => view.id === taskView.value)?.label || "任务"); const selectedTask = computed(() => availableTasks.value.find((task) => task.id === selectedTaskId.value) || currentTask.value || availableTasks.value[0] || null); const visibleTasks = computed(() => ({ inbox: inboxTasks.value, today: todayTasks.value, now: nowTasks.value })[taskView.value] || []); const focusTask = computed(() => todayTasks.value.find((task) => task.id === selectedTaskId.value) || currentTask.value || todayTasks.value[0] || null);
const WORKDAY_START_MINUTES = 8 * 60 + 30;
const WORKDAY_END_MINUTES = 20 * 60 + 30;
const WORKDAY_DURATION_MINUTES = WORKDAY_END_MINUTES - WORKDAY_START_MINUTES;
const hours = ["08:30", "10:00", "12:00", "14:00", "16:00", "18:00", "20:00", "20:30"];
const formatMinutes = (minutes) => minutes >= 60 ? `${Math.floor(minutes / 60)}h ${minutes % 60}m` : `${minutes}m`;
const formatTime = (seconds) => `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
const formattedTime = computed(() => { if (!activeTimer.value) return "00:00"; const elapsed = elapsedSeconds.value; return activeTimer.value.mode === "countdown" ? formatTime(Math.max(0, activeTimer.value.plannedSeconds - elapsed)) : formatTime(elapsed); });

const minutesFor = (time) => { const [h, m] = time.split(":").map(Number); return h * 60 + m; };
const clockTimeFor = (minutes) => `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`;
const openScheduleDialog = () => { const durationMinutes = 25; const nowMinutes = Number(props.currentTime.hour) * 60 + Number(props.currentTime.minute) + 15; const latestStart = WORKDAY_END_MINUTES - durationMinutes; scheduleForm.value = { taskId: selectedTask.value?.id || "", startTime: clockTimeFor(Math.min(latestStart, Math.max(WORKDAY_START_MINUTES, nowMinutes))), durationMinutes }; formError.value = ""; showScheduleDialog.value = true; };
const timePercent = (time) => Math.min(100, Math.max(0, ((minutesFor(time) - WORKDAY_START_MINUTES) / WORKDAY_DURATION_MINUTES) * 100));
const taskTitle = (taskId) => state.value.tasks.find((task) => task.id === taskId)?.title || "已归档任务";
const timelineItems = computed(() => {
  const planned = state.value.scheduleBlocks.filter((block) => block.workday === currentWorkday.value && block.status === "planned").map((block) => ({ id: block.id, blockId: block.id, title: taskTitle(block.taskId), duration: formatMinutes(block.durationMinutes), kind: "planned", style: { top: `${timePercent(block.startTime)}%`, height: `${Math.max(5, (block.durationMinutes / WORKDAY_DURATION_MINUTES) * 100)}%` } }));
  const actual = todaySessions.value.filter((session) => session.status === "completed").map((session) => {
    const d = new Date(session.startedAt);
    const time = `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
    return {
      id: session.id,
      title: taskTitle(session.taskId),
      duration: formatMinutes(Math.round(session.actualSeconds / 60)),
      kind: "completed",
      style: { top: `${timePercent(time)}%`, height: `${Math.max(5, (session.actualSeconds / (WORKDAY_DURATION_MINUTES * 60)) * 100)}%` },
    };
  });
  return [...planned, ...actual];
});
const nowPosition = computed(() => timePercent(`${props.currentTime.hour}:${props.currentTime.minute}`));

const tick = () => { elapsedSeconds.value = getElapsedSeconds(); if (activeTimer.value?.mode === "countdown" && activeTimer.value.status === "running" && elapsedSeconds.value >= activeTimer.value.plannedSeconds && !showFocusEndDialog.value) requestTimerEnd(); };
onMounted(() => { tick(); clock = window.setInterval(tick, 1000); }); onBeforeUnmount(() => window.clearInterval(clock));
watch(() => `${props.currentTime.year}-${props.currentTime.month}-${props.currentTime.day}-${props.currentTime.hour}-${props.currentTime.minute}`, refreshWorkday, { immediate: true });
const closeDialogs = () => { showTaskDialog.value = false; showScheduleDialog.value = false; showFocusEndDialog.value = false; showClearDialog.value = false; importPreview.value = null; formError.value = ""; clearPhrase.value = ""; };
const dismissBackdrop = () => { if (!showFocusEndDialog.value) closeDialogs(); };
const createTask = () => { try { const task = addTask(taskForm.value); selectedTaskId.value = task.id; taskView.value = "inbox"; taskForm.value = { title: "", quadrant: "important", estimatePomodoros: 1 }; closeDialogs(); } catch (error) { formError.value = error.message; } };
const startDefaultFocus = () => { try { startTimer({ taskId: focusTask.value?.id, mode: focusMode.value, durationMinutes: focusMode.value === "countdown" ? 25 : undefined }); taskView.value = "now"; tick(); } catch (error) { formError.value = error.message; } };
const requestTimerEnd = () => { if (!activeTimer.value) return; if (activeTimer.value.status === "running") pauseTimer(); tick(); showFocusEndDialog.value = true; };
const settleFocus = (action) => { settleTimer(action); closeDialogs(); tick(); taskView.value = action === "complete" ? "today" : "now"; };
const requestCompleteTask = (taskId) => { try { completeTask(taskId); } catch (error) { window.alert(error.message); } };
const requestDeleteTask = (taskId) => {
  const task = state.value.tasks.find((item) => item.id === taskId);
  if (!task) return;
  const active = activeTimer.value?.taskId === taskId;
  const message = active ? `删除“${task.title}”？正在进行的番茄钟不会保存，相关计划和记录也会一并删除。` : `删除“${task.title}”？相关计划和专注记录也会一并删除。`;
  if (!window.confirm(message)) return;
  deleteTask(taskId);
  if (selectedTaskId.value === taskId) selectedTaskId.value = "";
  if (active) { showFocusEndDialog.value = false; tick(); }
};
const moveVisibleTask = (index, direction) => {
  const target = visibleTasks.value[index + direction];
  const source = visibleTasks.value[index];
  if (!source || !target) return;
  moveTask(source.id, target.id);
};
const abandonTimer = () => { if (window.confirm("放弃当前专注？本次时长不会计入统计。")) { discardTimer(); tick(); } };
const createSchedule = () => { try { const startMinutes = minutesFor(scheduleForm.value.startTime); const endMinutes = startMinutes + Number(scheduleForm.value.durationMinutes); if (startMinutes < WORKDAY_START_MINUTES || endMinutes > WORKDAY_END_MINUTES) throw new Error("计划请安排在 08:30—20:30 内"); addScheduleBlock(scheduleForm.value); taskView.value = "today"; closeDialogs(); } catch (error) { formError.value = error.message; } };
const removePlannedBlock = (blockId) => { if (window.confirm("移除这个计划时间块？")) removeScheduleBlock(blockId); };
const downloadExport = () => { downloadFile(exportData(), `homepage-pomodoro-${currentWorkday.value}.json`, "application/json"); showDataMenu.value = false; };

const downloadExcel = () => { downloadFile(createExcelWorkbook(state.value), `homepage-focus-${currentWorkday.value}.xls`, "application/vnd.ms-excel;charset=utf-8"); showDataMenu.value = false; };
const prepareImport = async (event) => { const file = event.target.files?.[0]; if (!file) return; try { const text = await file.text(); const parsed = JSON.parse(text); if (!Array.isArray(parsed.tasks) || !Array.isArray(parsed.scheduleBlocks) || !Array.isArray(parsed.focusSessions)) throw new Error("文件格式不正确"); importText.value = text; importPreview.value = parsed; showDataMenu.value = false; } catch (error) { window.alert(error.message || "无法读取备份文件"); } finally { event.target.value = ""; } };
const applyImport = (mode) => { try { importData(importText.value, mode); closeDialogs(); } catch (error) { window.alert(error.message); } };
const openClearDialog = () => { showDataMenu.value = false; showClearDialog.value = true; };
const confirmClear = () => { if (clearPhrase.value === "清空") { clearAllData(); selectedTaskId.value = ""; closeDialogs(); } };
</script>

<style lang="scss" scoped>
.workday{position:relative;width:min(100%,590px);padding:clamp(1.1rem,2vw,1.5rem);color:var(--text-color)}.panel-header,.section-title,.focus-now,.summary{display:flex;align-items:center;justify-content:space-between;gap:1rem}.panel-header h1,.section-title h2,.focus-now h2,p{margin:0}.panel-header h1{font-size:1.38rem;font-weight:650}.eyebrow{color:var(--muted-text);font-size:.62rem;font-weight:700;letter-spacing:.16em}.header-actions{display:flex;align-items:center;gap:.4rem}.date-label,.section-title>span{color:var(--muted-text);font-size:.76rem;white-space:nowrap}.icon-button,.text-button,.timer button{border:0;border-radius:.5rem;background:transparent;color:inherit;cursor:pointer;font:inherit}.icon-button{padding:.2rem .45rem;font-size:1.1rem}.data-menu{position:absolute;z-index:5;top:3.7rem;right:1.25rem;display:grid;min-width:9.5rem;padding:.35rem;border:1px solid var(--surface-border);border-radius:.7rem;background:#182839ef;box-shadow:0 12px 30px rgb(0 0 0 / 24%)}.data-menu button{padding:.55rem .6rem;border:0;border-radius:.4rem;background:transparent;color:inherit;text-align:left;cursor:pointer}.data-menu button:hover{background:var(--surface-hover)}.data-menu .danger{color:#ffc0b9}.summary{margin:1.15rem 0;padding:.8rem 0;border-top:1px solid var(--surface-border);border-bottom:1px solid var(--surface-border)}.summary div{display:grid;gap:.18rem}.summary strong{font-size:1rem;font-weight:650}.summary span,.focus-now small{color:var(--muted-text);font-size:.7rem}.focus-now{padding:.9rem 1rem;border:1px solid var(--surface-border);border-radius:1rem;background:rgb(255 255 255 / 10%)}.focus-now.running{border-color:rgb(214 244 195 / 65%);box-shadow:0 0 0 3px rgb(214 244 195 / 10%)}.focus-copy{min-width:0}.focus-copy p{display:inline;color:var(--muted-text);font-size:.72rem}.focus-now h2{overflow:hidden;margin:.25rem 0;font-size:.96rem;text-overflow:ellipsis;white-space:nowrap}.status-dot{display:inline-block;width:.45rem;height:.45rem;margin-right:.38rem;b